import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` readable under `notes`.

    Each name is resolved relative to the directory `notes` (in the working
    directory); subdirectory names such as "sub/b.txt" are allowed. Names are
    untrusted: any name that would reach a file outside `notes` (via "..",
    absolute paths, symlinks, NUL bytes, or any other spelling) is treated as
    unreadable and skipped. Missing, unreadable, or non-file entries are also
    skipped. Returns "" when the list is empty or no name is readable.
    """
    try:
        base = Path(NOTES_DIR).resolve()
    except (OSError, ValueError, RuntimeError):
        return ""
    for name in names:
        if "\x00" in name or os.path.isabs(name):
            continue
        try:
            target = (base / name).resolve()
            if not target.is_relative_to(base):
                continue
            if not target.is_file():
                continue
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError, RuntimeError):
            continue
    return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / NOTES_DIR / "sub").mkdir(parents=True)
    (tmp_path / NOTES_DIR / "a.txt").write_text("alpha")
    (tmp_path / NOTES_DIR / "sub" / "b.txt").write_text("beta")
    (tmp_path / "secret.txt").write_text("SECRET")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("SIBLING")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_simple_file(root: Path) -> None:
    assert first_readable(["a.txt"]) == "alpha"


def test_reads_subdirectory_file(root: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "beta"


def test_empty_list(root: Path) -> None:
    assert first_readable([]) == ""


def test_missing_returns_empty(root: Path) -> None:
    assert first_readable(["nope.txt"]) == ""


def test_skips_missing_to_next(root: Path) -> None:
    assert first_readable(["nope.txt", "sub/b.txt", "a.txt"]) == "beta"


def test_first_readable_wins(root: Path) -> None:
    assert first_readable(["a.txt", "sub/b.txt"]) == "alpha"


def test_directory_name_is_skipped(root: Path) -> None:
    assert first_readable(["sub", "", ".", "a.txt"]) == "alpha"
    assert first_readable(["sub"]) == ""


def test_parent_traversal_blocked(root: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["../../secret.txt", "a.txt"]) == "alpha"


def test_traversal_via_notes_prefix_blocked(root: Path) -> None:
    assert first_readable(["notes/../../secret.txt"]) == ""
    assert first_readable(["../notes/../secret.txt"]) == ""


def test_sibling_directory_with_shared_prefix_blocked(root: Path) -> None:
    assert first_readable(["../notes2/x.txt"]) == ""


def test_absolute_path_outside_blocked(root: Path) -> None:
    assert first_readable([str(root / "secret.txt")]) == ""
    assert first_readable(["/etc/passwd"]) == ""


def test_absolute_path_inside_notes_not_trusted_as_outside(root: Path) -> None:
    # An absolute path is never allowed to escape; a later valid name still works.
    assert first_readable([str(root / "secret.txt"), "a.txt"]) == "alpha"


def test_backslash_and_odd_spellings_blocked(root: Path) -> None:
    assert first_readable(["..\\secret.txt"]) == ""
    assert first_readable(["./../secret.txt"]) == ""
    assert first_readable(["sub//../../secret.txt"]) == ""


def test_dotdot_staying_inside_is_ok(root: Path) -> None:
    assert first_readable(["sub/../a.txt"]) == "alpha"


def test_nul_byte_name_skipped(root: Path) -> None:
    assert first_readable(["a.txt\x00../secret.txt"]) == ""
    assert first_readable(["\x00", "a.txt"]) == "alpha"


def test_symlink_file_escaping_blocked(root: Path) -> None:
    os.symlink(root / "secret.txt", root / NOTES_DIR / "link.txt")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "alpha"


def test_symlink_dir_escaping_blocked(root: Path) -> None:
    os.symlink(root / "notes2", root / NOTES_DIR / "linkdir")
    assert first_readable(["linkdir/x.txt"]) == ""


def test_symlink_inside_notes_allowed(root: Path) -> None:
    os.symlink(root / NOTES_DIR / "a.txt", root / NOTES_DIR / "inner.txt")
    assert first_readable(["inner.txt"]) == "alpha"


def test_unreadable_file_skipped(root: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read anything")
    locked = root / NOTES_DIR / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt"]) == ""
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
    finally:
        locked.chmod(0o600)


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "secret.txt").write_text("SECRET")
    assert first_readable(["a.txt", "../secret.txt"]) == ""

